import com.example.chessrepertoiretrainer.database.entities.PlayerProfile
import com.example.chessrepertoiretrainer.ui.viewmodels.PlayerProfilesViewModel

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun PlayerProfilesScreen(
    viewModel: PlayerProfilesViewModel,
    onOpenProfileTree: (Long) -> Unit
) {
    val profiles by viewModel.profiles.collectAsState()
    val uiState by viewModel.uiState.collectAsState()

    val (username, setUsername) = remember { mutableStateOf("") }
    val (platform, setPlatform) = remember { mutableStateOf("lichess") }

    Scaffold(
        topBar = {
            TopAppBar(title = { Text("Players") })
        }
    ) { padding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
                .padding(16.dp)
        ) {
            Text(
                text = "Track a player for opening analysis",
                style = MaterialTheme.typography.titleMedium
            )

            Spacer(modifier = Modifier.height(8.dp))

            OutlinedTextField(
                value = username,
                onValueChange = setUsername,
                label = { Text("Username") },
                modifier = Modifier.fillMaxWidth()
            )

            Spacer(modifier = Modifier.height(8.dp))

            Text(text = "Platform", style = MaterialTheme.typography.labelMedium)
            Row(
                verticalAlignment = Alignment.CenterVertically
            ) {
                RadioButton(
                    selected = platform == "lichess",
                    onClick = { setPlatform("lichess") }
                )
                Text(text = "Lichess")
                Spacer(modifier = Modifier.width(16.dp))
                RadioButton(
                    selected = platform == "chess.com",
                    onClick = { setPlatform("chess.com") }
                )
                Text(text = "Chess.com")
            }

            Spacer(modifier = Modifier.height(8.dp))

            Button(
                onClick = {
                    viewModel.addProfile(username, platform)
                },
                enabled = username.isNotBlank()
            ) {
                Text("Add player")
            }

            if (uiState.errorMessage != null) {
                Spacer(modifier = Modifier.height(8.dp))
                Text(
                    text = uiState.errorMessage ?: "",
                    color = MaterialTheme.colorScheme.error,
                    style = MaterialTheme.typography.bodySmall
                )
            }

            uiState.lastSyncSummary?.let { summary ->
                Spacer(modifier = Modifier.height(8.dp))
                Text(
                    text = summary,
                    style = MaterialTheme.typography.bodySmall
                )
            }

            if (uiState.isSyncing) {
                Spacer(modifier = Modifier.height(4.dp))
                Text(
                    text = "Syncing games...",
                    style = MaterialTheme.typography.bodySmall,
                    color = MaterialTheme.colorScheme.primary
                )
            }

            Spacer(modifier = Modifier.height(16.dp))

            Text(
                text = "Tracked players",
                style = MaterialTheme.typography.titleMedium
            )

            Spacer(modifier = Modifier.height(8.dp))

            LazyColumn(
                modifier = Modifier.fillMaxWidth(),
                verticalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                items(profiles) { profile ->
                    PlayerProfileRow(
                        profile = profile,
                        onOpenTreeClick = { onOpenProfileTree(profile.id) },
                        onSyncClick = { viewModel.syncGamesForProfile(profile.id, maxGames = 100) },
                        isSyncing = uiState.isSyncing
                    )
                }
            }
        }
    }
}

@Composable
private fun PlayerProfileRow(
    profile: PlayerProfile,
    onOpenTreeClick: () -> Unit,
    onSyncClick: () -> Unit,
    isSyncing: Boolean
) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .padding(vertical = 4.dp),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically
    ) {
        Column {
            Text(text = profile.username, style = MaterialTheme.typography.bodyLarge)
            Text(text = profile.platform, style = MaterialTheme.typography.bodySmall)
        }
        Row(verticalAlignment = Alignment.CenterVertically) {
            Button(
                onClick = onSyncClick,
                enabled = !isSyncing
            ) {
                Text(if (isSyncing) "Syncing..." else "Download games")
            }
            Spacer(modifier = Modifier.width(8.dp))
            Button(onClick = onOpenTreeClick) {
                Text("Open tree")
            }
        }
    }
}

