import com.example.chessrepertoiretrainer.database.entities.PlayerProfile
import com.example.chessrepertoiretrainer.ui.viewmodels.PlayerProfilesViewModel

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun PlayerProfilesScreen(
  viewModel: PlayerProfilesViewModel,
  onOpenProfileTree: (profileId: Long, color: String, timeControl: String) -> Unit
) {
  val uiState by viewModel.uiState.collectAsState()

  val (username, setUsername) = remember { mutableStateOf("") }
  val (platform, setPlatform) = remember { mutableStateOf("lichess") }
  val (colorFilter, setColorFilter) = remember { mutableStateOf("both") }
  val (timeControlFilter, setTimeControlFilter) = remember { mutableStateOf("") }
  val (maxGamesText, setMaxGamesText) = remember { mutableStateOf("200") }

    Scaffold(
        topBar = {
                  TopAppBar(title = { Text("Your games") })
        }
    ) { padding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
                .padding(16.dp)
        ) {
                  Text(
                    text = "Download your games for opening analysis",
                    style = MaterialTheme.typography.titleMedium
                  )

            Spacer(modifier = Modifier.height(8.dp))

            OutlinedTextField(
                value = username,
                onValueChange = setUsername,
                label = { Text("Username") },
                modifier = Modifier.fillMaxWidth()
            )

            Spacer(modifier = Modifier.height(8.dp))

                  Text(text = "Platform", style = MaterialTheme.typography.labelMedium)
            Row(
                verticalAlignment = Alignment.CenterVertically
            ) {
                RadioButton(
                    selected = platform == "lichess",
                    onClick = { setPlatform("lichess") }
                )
                Text(text = "Lichess")
                Spacer(modifier = Modifier.width(16.dp))
                RadioButton(
                    selected = platform == "chess.com",
                    onClick = { setPlatform("chess.com") }
                )
                Text(text = "Chess.com")
            }

                  Spacer(modifier = Modifier.height(8.dp))

                  Text(text = "Color", style = MaterialTheme.typography.labelMedium)
                  Row(verticalAlignment = Alignment.CenterVertically) {
                    RadioButton(
                      selected = colorFilter == "both",
                      onClick = { setColorFilter("both") }
                    )
                    Text(text = "Both")
                    Spacer(modifier = Modifier.width(16.dp))
                    RadioButton(
                      selected = colorFilter == "white",
                      onClick = { setColorFilter("white") }
                    )
                    Text(text = "White")
                    Spacer(modifier = Modifier.width(16.dp))
                    RadioButton(
                      selected = colorFilter == "black",
                      onClick = { setColorFilter("black") }
                    )
                    Text(text = "Black")
                  }

                  Spacer(modifier = Modifier.height(8.dp))

                  OutlinedTextField(
                    value = timeControlFilter,
                    onValueChange = setTimeControlFilter,
                    label = { Text("Time control filter (optional)") },
                    modifier = Modifier.fillMaxWidth()
                  )

                  Spacer(modifier = Modifier.height(8.dp))

                  OutlinedTextField(
                    value = maxGamesText,
                    onValueChange = { newValue ->
                      // Allow only digits or empty string
                      if (newValue.all { it.isDigit() } ) {
                        setMaxGamesText(newValue)
                      }
                    },
                    label = { Text("Max games to download (empty = all)") },
                    modifier = Modifier.fillMaxWidth()
                  )

                  Spacer(modifier = Modifier.height(8.dp))

                  Button(
                    onClick = {
                      val maxGames = maxGamesText.toIntOrNull()
                      viewModel.syncGamesForUsername(
                        username = username,
                        platform = platform,
                        maxGames = maxGames
                      ) { profileId ->
                        onOpenProfileTree(profileId, colorFilter, timeControlFilter)
                      }
                    },
                    enabled = username.isNotBlank() && !uiState.isSyncing
                  ) {
                    Text(if (uiState.isSyncing) "Syncing..." else "Download games and open tree")
                  }

            if (uiState.errorMessage != null) {
                Spacer(modifier = Modifier.height(8.dp))
                Text(
                    text = uiState.errorMessage ?: "",
                    color = MaterialTheme.colorScheme.error,
                    style = MaterialTheme.typography.bodySmall
                )
            }

                  uiState.lastSyncSummary?.let { summary ->
                    Spacer(modifier = Modifier.height(8.dp))
                    Text(
                      text = summary,
                      style = MaterialTheme.typography.bodySmall
                    )
                  }

                  if (uiState.isSyncing) {
                    Spacer(modifier = Modifier.height(4.dp))
                    Text(
                      text = "Syncing games...",
                      style = MaterialTheme.typography.bodySmall,
                      color = MaterialTheme.colorScheme.primary
                    )
                  }
        }
    }
}

package com.example.chessrepertoiretrainer.ui.viewmodels

import androidx.lifecycle.ViewModel
import androidx.lifecycle.ViewModelProvider
import androidx.lifecycle.viewModelScope
import androidx.lifecycle.viewmodel.CreationExtras
import com.example.chessrepertoiretrainer.data.GameForOpeningTree
import com.example.chessrepertoiretrainer.data.OpeningTree
import com.example.chessrepertoiretrainer.data.OpeningTreeBuilder
import com.example.chessrepertoiretrainer.data.PlayerGamesRepository
import com.example.chessrepertoiretrainer.ui.components.chess.DefaultChessBoardController
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

class OpeningTreeViewModel(
    private val profileId: Long,
    private val gamesRepository: PlayerGamesRepository
) : ViewModel() {

    val chessController = DefaultChessBoardController()

    private var openingTree: OpeningTree? = null

    private val _uiState = MutableStateFlow(OpeningTreeUiState())
    val uiState: StateFlow<OpeningTreeUiState> = _uiState.asStateFlow()

    init {
        viewModelScope.launch {
            rebuildOpeningTree()
        }
    }

    private suspend fun rebuildOpeningTree() {
        val gamesWithPgn = gamesRepository.getGamesWithPgnForProfile(profileId)
        if (gamesWithPgn.isEmpty()) {
            openingTree = null
            _uiState.value = OpeningTreeUiState()
            chessController.resetBoard()
            return
        }

        val gamesForTree = gamesWithPgn.map { gwp ->
            GameForOpeningTree(
                pgn = gwp.pgn,
                isUserWhite = gwp.game.isUserWhite,
                resultTag = gwp.game.result
            )
        }

        openingTree = OpeningTreeBuilder.buildTree(gamesForTree)
        val tree = openingTree
        if (tree == null) {
            _uiState.value = OpeningTreeUiState()
            chessController.resetBoard()
        } else {
            applyFen(tree.rootFen, tree)
        }
    }

    private fun applyFen(fen: String, tree: OpeningTree) {
        val node = tree.getNode(fen) ?: run {
            _uiState.value = OpeningTreeUiState()
            chessController.resetBoard()
            return
        }

        val movesUi = node.children.values
            .sortedByDescending { it.games }
            .map { agg ->
                val total = if (agg.games <= 0) 1 else agg.games
                val winPercent = (agg.wins * 100) / total
                val drawPercent = (agg.draws * 100) / total
                val lossPercent = (agg.losses * 100) / total

                OpeningTreeMoveUi(
                    moveSan = agg.moveSan,
                    toFen = agg.toFen,
                    games = agg.games,
                    winPercent = winPercent,
                    drawPercent = drawPercent,
                    lossPercent = lossPercent
                )
            }

        val path = buildPathForNode(node, tree)

        _uiState.value = OpeningTreeUiState(
            currentFen = fen,
            pathMoves = path,
            moves = movesUi
        )

        chessController.loadPositionFromFen(fen)
    }

    private fun buildPathForNode(
        node: com.example.chessrepertoiretrainer.data.OpeningTreeNode,
        tree: OpeningTree
    ): List<String> {
        val path = mutableListOf<String>()
        var current: com.example.chessrepertoiretrainer.data.OpeningTreeNode? = node
        while (current != null && current.moveSanFromParent != null) {
            path.add(current.moveSanFromParent)
            val parentFen = current.parentFen
            current = if (parentFen != null) tree.getNode(parentFen) else null
        }
        return path.asReversed()
    }

    fun onMoveSelected(targetFen: String) {
        val tree = openingTree ?: return
        val node = tree.getNode(targetFen) ?: return
        applyFen(node.fen, tree)
    }

    fun onGoBack() {
        val tree = openingTree ?: return
        val currentFen = _uiState.value.currentFen ?: return
        val node = tree.getNode(currentFen) ?: return
        val parentFen = node.parentFen ?: return
        val parentNode = tree.getNode(parentFen) ?: return
        applyFen(parentNode.fen, tree)
    }

    fun onGoRoot() {
        val tree = openingTree ?: return
        applyFen(tree.rootFen, tree)
    }

    data class OpeningTreeMoveUi(
        val moveSan: String,
        val toFen: String,
        val games: Int,
        val winPercent: Int,
        val drawPercent: Int,
        val lossPercent: Int
    )

    data class OpeningTreeUiState(
        val currentFen: String? = null,
        val pathMoves: List<String> = emptyList(),
        val moves: List<OpeningTreeMoveUi> = emptyList()
    )

    class Factory(
        private val profileId: Long,
        private val gamesRepository: PlayerGamesRepository
    ) : ViewModelProvider.Factory {
        @Suppress("UNCHECKED_CAST")
        override fun <T : ViewModel> create(modelClass: Class<T>, extras: CreationExtras): T {
            return OpeningTreeViewModel(profileId, gamesRepository) as T
        }
    }
}

package com.example.chessrepertoiretrainer.ui.viewmodels

import androidx.lifecycle.ViewModel
import androidx.lifecycle.ViewModelProvider
import androidx.lifecycle.viewModelScope
import androidx.lifecycle.viewmodel.CreationExtras
import com.example.chessrepertoiretrainer.data.GameForOpeningTree
import com.example.chessrepertoiretrainer.data.OpeningTree
import com.example.chessrepertoiretrainer.data.OpeningTreeBuilder
import com.example.chessrepertoiretrainer.data.PlayerGamesRepository
import com.example.chessrepertoiretrainer.ui.components.chess.DefaultChessBoardController
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

class OpeningTreeViewModel(
  private val profileId: Long,
  private val gamesRepository: PlayerGamesRepository,
  private val colorFilter: ColorFilter = ColorFilter.BOTH,
  private val timeControlFilter: String? = null
) : ViewModel() {

    val chessController = DefaultChessBoardController()

    private var openingTree: OpeningTree? = null

    private val _uiState = MutableStateFlow(OpeningTreeUiState())
    val uiState: StateFlow<OpeningTreeUiState> = _uiState.asStateFlow()

    init {
        viewModelScope.launch {
            rebuildOpeningTree()
        }
    }

      private suspend fun rebuildOpeningTree() {
        val allGamesWithPgn = gamesRepository.getGamesWithPgnForProfile(profileId)
        val gamesWithPgn = applyFilters(allGamesWithPgn)
        if (gamesWithPgn.isEmpty()) {
          openingTree = null
          _uiState.value = OpeningTreeUiState()
          chessController.resetBoard()
          return
        }

        val gamesForTree = gamesWithPgn.map { gwp ->
            GameForOpeningTree(
                pgn = gwp.pgn,
                isUserWhite = gwp.game.isUserWhite,
                resultTag = gwp.game.result
            )
        }

        openingTree = OpeningTreeBuilder.buildTree(gamesForTree)
        val tree = openingTree
        if (tree == null) {
            _uiState.value = OpeningTreeUiState()
            chessController.resetBoard()
        } else {
            applyFen(tree.rootFen, tree)
        }
    }

    private fun applyFen(fen: String, tree: OpeningTree) {
        val node = tree.getNode(fen) ?: run {
            _uiState.value = OpeningTreeUiState()
            chessController.resetBoard()
            return
        }

        val movesUi = node.children.values
            .sortedByDescending { it.games }
            .map { agg ->
                val total = if (agg.games <= 0) 1 else agg.games
                val winPercent = (agg.wins * 100) / total
                val drawPercent = (agg.draws * 100) / total
                val lossPercent = (agg.losses * 100) / total

                OpeningTreeMoveUi(
                    moveSan = agg.moveSan,
                    toFen = agg.toFen,
                    games = agg.games,
                    winPercent = winPercent,
                    drawPercent = drawPercent,
                    lossPercent = lossPercent
                )
            }

        val path = buildPathForNode(node, tree)

        _uiState.value = OpeningTreeUiState(
            currentFen = fen,
            pathMoves = path,
            moves = movesUi
        )

        chessController.loadPositionFromFen(fen)
    }

    private fun buildPathForNode(
        node: com.example.chessrepertoiretrainer.data.OpeningTreeNode,
        tree: OpeningTree
    ): List<String> {
        val path = mutableListOf<String>()
        var current: com.example.chessrepertoiretrainer.data.OpeningTreeNode? = node
        while (current != null && current.moveSanFromParent != null) {
            path.add(current.moveSanFromParent)
            val parentFen = current.parentFen
            current = if (parentFen != null) tree.getNode(parentFen) else null
        }
        return path.asReversed()
    }

    fun onMoveSelected(targetFen: String) {
        val tree = openingTree ?: return
        val node = tree.getNode(targetFen) ?: return
        applyFen(node.fen, tree)
    }

    fun onGoBack() {
        val tree = openingTree ?: return
        val currentFen = _uiState.value.currentFen ?: return
        val node = tree.getNode(currentFen) ?: return
        val parentFen = node.parentFen ?: return
        val parentNode = tree.getNode(parentFen) ?: return
        applyFen(parentNode.fen, tree)
    }

    fun onGoRoot() {
        val tree = openingTree ?: return
        applyFen(tree.rootFen, tree)
    }

    data class OpeningTreeMoveUi(
        val moveSan: String,
        val toFen: String,
        val games: Int,
        val winPercent: Int,
        val drawPercent: Int,
        val lossPercent: Int
    )

    data class OpeningTreeUiState(
        val currentFen: String? = null,
        val pathMoves: List<String> = emptyList(),
        val moves: List<OpeningTreeMoveUi> = emptyList()
    )

      enum class ColorFilter { BOTH, WHITE_ONLY, BLACK_ONLY }

      private fun applyFilters(games: List<com.example.chessrepertoiretrainer.data.GameWithPgn>): List<com.example.chessrepertoiretrainer.data.GameWithPgn> {
        var sequence = games.asSequence()

        sequence = when (colorFilter) {
          ColorFilter.BOTH -> sequence
          ColorFilter.WHITE_ONLY -> sequence.filter { it.game.isUserWhite }
          ColorFilter.BLACK_ONLY -> sequence.filter { !it.game.isUserWhite }
        }

        val tc = timeControlFilter?.trim().orEmpty()
        if (tc.isNotEmpty()) {
          sequence = sequence.filter { gwp ->
            gwp.game.timeControl?.contains(tc, ignoreCase = true) == true
          }
        }

        return sequence.toList()
      }

      class Factory(
        private val profileId: Long,
        private val gamesRepository: PlayerGamesRepository,
        private val colorFilter: ColorFilter,
        private val timeControlFilter: String?
      ) : ViewModelProvider.Factory {
        @Suppress("UNCHECKED_CAST")
        override fun <T : ViewModel> create(modelClass: Class<T>, extras: CreationExtras): T {
          return OpeningTreeViewModel(
            profileId = profileId,
            gamesRepository = gamesRepository,
            colorFilter = colorFilter,
            timeControlFilter = timeControlFilter
          ) as T
        }
      }
}

package com.example.chessrepertoiretrainer.ui.viewmodels

import androidx.lifecycle.ViewModel
import androidx.lifecycle.ViewModelProvider
import androidx.lifecycle.viewModelScope
import androidx.lifecycle.viewmodel.CreationExtras
import com.example.chessrepertoiretrainer.data.PlayerGamesRepository
import com.example.chessrepertoiretrainer.data.PlayerProfileRepository
import com.example.chessrepertoiretrainer.database.entities.PlayerProfile
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.launch

/**
 * ViewModel for managing tracked player profiles used for opening-tree
 * analysis.
 */
 class PlayerProfilesViewModel(
    private val repository: PlayerProfileRepository,
    private val gamesRepository: PlayerGamesRepository
 ) : ViewModel() {

    val profiles: StateFlow<List<PlayerProfile>> =
        repository.getAllProfiles()
            .stateIn(
                scope = viewModelScope,
                started = SharingStarted.WhileSubscribed(5000),
                initialValue = emptyList()
            )

    private val _uiState = MutableStateFlow(PlayerProfilesUiState())
    val uiState: StateFlow<PlayerProfilesUiState> = _uiState.asStateFlow()

    fun addProfile(username: String, platform: String) {
        if (username.isBlank()) return
        viewModelScope.launch {
            try {
                repository.addOrUpdateProfile(username, platform)
                _uiState.value = PlayerProfilesUiState()
            } catch (e: Exception) {
                _uiState.value = PlayerProfilesUiState(errorMessage = e.message)
            }
        }
    }

    /**
     * Trigger download/synchronization of games for a given player profile.
     */
    fun syncGamesForProfile(profileId: Long, maxGames: Int? = null) {
        if (_uiState.value.isSyncing) return

        viewModelScope.launch {
            _uiState.value = _uiState.value.copy(
                isSyncing = true,
                errorMessage = null,
                lastSyncSummary = null
            )

            val result = try {
                gamesRepository.syncGamesForProfile(profileId, maxGames)
            } catch (e: Exception) {
                _uiState.value = _uiState.value.copy(
                    isSyncing = false,
                    errorMessage = e.message ?: "Unexpected error during sync"
                )
                return@launch
            }

            _uiState.value = _uiState.value.copy(
                isSyncing = false,
                errorMessage = result.errorMessage,
                lastSyncSummary = if (result.errorMessage == null) {
                    "Downloaded ${result.newGames} new games"
                } else {
                    null
                }
            )
        }
    }

    fun clearError() {
        _uiState.value = _uiState.value.copy(errorMessage = null)
    }

    data class PlayerProfilesUiState(
        val errorMessage: String? = null,
        val isSyncing: Boolean = false,
        val lastSyncSummary: String? = null
    )

    class Factory(
        private val repository: PlayerProfileRepository,
        private val gamesRepository: PlayerGamesRepository
    ) : ViewModelProvider.Factory {
        @Suppress("UNCHECKED_CAST")
        override fun <T : ViewModel> create(modelClass: Class<T>, extras: CreationExtras): T {
            return PlayerProfilesViewModel(repository, gamesRepository) as T
        }
    }
}

package com.example.chessrepertoiretrainer.ui.viewmodels

import androidx.lifecycle.ViewModel
import androidx.lifecycle.ViewModelProvider
import androidx.lifecycle.viewModelScope
import androidx.lifecycle.viewmodel.CreationExtras
import com.example.chessrepertoiretrainer.data.PlayerGamesRepository
import com.example.chessrepertoiretrainer.data.PlayerProfileRepository
import com.example.chessrepertoiretrainer.database.entities.PlayerProfile
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.launch

/**
 * ViewModel for managing tracked player profiles used for opening-tree
 * analysis.
 */
 class PlayerProfilesViewModel(
    private val repository: PlayerProfileRepository,
    private val gamesRepository: PlayerGamesRepository
 ) : ViewModel() {

    val profiles: StateFlow<List<PlayerProfile>> =
        repository.getAllProfiles()
            .stateIn(
                scope = viewModelScope,
                started = SharingStarted.WhileSubscribed(5000),
                initialValue = emptyList()
            )

    private val _uiState = MutableStateFlow(PlayerProfilesUiState())
    val uiState: StateFlow<PlayerProfilesUiState> = _uiState.asStateFlow()

    fun addProfile(username: String, platform: String) {
        if (username.isBlank()) return
        viewModelScope.launch {
            try {
                repository.addOrUpdateProfile(username, platform)
                _uiState.value = PlayerProfilesUiState()
            } catch (e: Exception) {
                _uiState.value = PlayerProfilesUiState(errorMessage = e.message)
            }
        }

                  /**
                   * Convenience helper used by the "Your games" screen: ensure there is a
                   * profile for the given username+platform, download games for it, and then
                   * invoke [onProfileReady] with the profile id so the UI can open the
                   * opening-tree screen.
                   */
                  fun syncGamesForUsername(
                    username: String,
                    platform: String,
                    maxGames: Int?,
                    onProfileReady: (Long) -> Unit
                  ) {
                    if (username.isBlank() || _uiState.value.isSyncing) return

                    viewModelScope.launch {
                      _uiState.value = _uiState.value.copy(
                        isSyncing = true,
                        errorMessage = null,
                        lastSyncSummary = null
                      )

                      val profile = try {
                        repository.getOrCreateProfile(username, platform)
                      } catch (e: Exception) {
                        _uiState.value = _uiState.value.copy(
                          isSyncing = false,
                          errorMessage = e.message ?: "Unexpected error while preparing profile"
                        )
                        return@launch
                      }

                      val result = try {
                        gamesRepository.syncGamesForProfile(profile.id, maxGames)
                      } catch (e: Exception) {
                        _uiState.value = _uiState.value.copy(
                          isSyncing = false,
                          errorMessage = e.message ?: "Unexpected error during sync"
                        )
                        return@launch
                      }

                      _uiState.value = _uiState.value.copy(
                        isSyncing = false,
                        errorMessage = result.errorMessage,
                        lastSyncSummary = if (result.errorMessage == null) {
                          "Downloaded ${result.newGames} new games"
                        } else {
                          null
                        }
                      )

                      onProfileReady(profile.id)
                    }
                  }
    }

    /**
     * Trigger download/synchronization of games for a given player profile.
     */
    fun syncGamesForProfile(profileId: Long, maxGames: Int? = null) {
        if (_uiState.value.isSyncing) return

        viewModelScope.launch {
            _uiState.value = _uiState.value.copy(
                isSyncing = true,
                errorMessage = null,
                lastSyncSummary = null
            )

            val result = try {
                gamesRepository.syncGamesForProfile(profileId, maxGames)
            } catch (e: Exception) {
                _uiState.value = _uiState.value.copy(
                    isSyncing = false,
                    errorMessage = e.message ?: "Unexpected error during sync"
                )
                return@launch
            }

            _uiState.value = _uiState.value.copy(
                isSyncing = false,
                errorMessage = result.errorMessage,
                lastSyncSummary = if (result.errorMessage == null) {
                    "Downloaded ${result.newGames} new games"
                } else {
                    null
                }
            )
        }
    }

    fun clearError() {
        _uiState.value = _uiState.value.copy(errorMessage = null)
    }

    data class PlayerProfilesUiState(
        val errorMessage: String? = null,
        val isSyncing: Boolean = false,
        val lastSyncSummary: String? = null
    )

    class Factory(
        private val repository: PlayerProfileRepository,
        private val gamesRepository: PlayerGamesRepository
    ) : ViewModelProvider.Factory {
        @Suppress("UNCHECKED_CAST")
        override fun <T : ViewModel> create(modelClass: Class<T>, extras: CreationExtras): T {
            return PlayerProfilesViewModel(repository, gamesRepository) as T
        }
    }
}
